public class ArrayDemo {
    public static void main(String[] args) {

        // 1. Declare and initialise using array literal
        int[] marks = {85, 90, 78, 92, 88};

        // 2. Print total number of elements
        System.out.println("Total subjects: " + marks.length);

        // 3. Access individual elements
        System.out.println("First subject marks: " + marks[0]);
        System.out.println("Last subject marks: " + marks[marks.length - 1]);

        // 4. Modify an element
        marks[2] = 95;
        System.out.println("Updated 3rd subject marks: " + marks[2]);

        // 5. Loop through array using regular for loop
        System.out.println("\nAll marks (regular for loop):");
        for (int i = 0; i < marks.length; i++) {
            System.out.println("Subject " + (i + 1) + ": " + marks[i]);
        }

        // 6. Loop through array using enhanced for loop
        System.out.println("\nAll marks (enhanced for loop):");
        int total = 0;
        for (int m : marks) {
            total += m;
        }
        System.out.println("Total marks: " + total);
        System.out.println("Average marks: " + (total / marks.length));
    }
}

